mod solution;

fn main() {
    let cases = [
    (r#"[1,4,7];[2,5,8];[0,6,9]"#, r#"0,1,2,4,5,6,7,8,9"#),
    (r#"[1,10];[2,3];[4]"#, r#"1,2,3,4,10"#),
    (r#"
[1,10];[2,3];[4]
"#, r#"1,2,3,4,10"#),
    (r#"  
[1,4,7];[2,5,8];[0,6,9]
  "#, r#"0,1,2,4,5,6,7,8,9"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS k-way-merge");
}
